def _parse_iso(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def _is_aware(dt):
    return dt.tzinfo is not None and dt.tzinfo.utcoffset(dt) is not None


def select_latest(rows, asof):
    if not isinstance(asof, datetime):
        raise ValueError('asof must be a datetime')
    if not _is_aware(asof):
        raise ValueError('asof must be timezone-aware')

    if rows is None:
        return None

    best = None
    best_obs = None
    best_id = None

    for row in rows:
        if not isinstance(row, dict):
            continue

        if 'id' not in row or 'odds' not in row or 'observed_at' not in row or 'expires_at' not in row:
            continue

        row_id = row['id']
        if not isinstance(row_id, str) or not row_id:
            continue

        try:
            american_probability(row['odds'])
        except (ValueError, TypeError):
            continue

        obs_raw = row['observed_at']
        if not isinstance(obs_raw, str):
            continue
        try:
            obs = _parse_iso(obs_raw)
        except (ValueError, TypeError, OverflowError):
            continue
        if not _is_aware(obs):
            continue

        exp_raw = row['expires_at']
        if not isinstance(exp_raw, str):
            continue
        try:
            exp = _parse_iso(exp_raw)
        except (ValueError, TypeError, OverflowError):
            continue
        if not _is_aware(exp):
            continue

        if not (obs <= asof < exp):
            continue
        if not (obs < exp):
            continue

        if best is None or obs > best_obs or (obs == best_obs and row_id < best_id):
            best = row
            best_obs = obs
